// components/scroll-progress.tsx
"use client";

import { useLayoutEffect, useRef } from "react";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

export function ScrollProgress() {
  const barRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    gsap.registerPlugin(ScrollTrigger);

    const bar = barRef.current;
    if (!bar) return;

    const setProgress = gsap.quickSetter(bar, "scaleX");

    gsap.set(bar, {
      scaleX: 0,
      transformOrigin: "left center",
    });

    const trigger = ScrollTrigger.create({
      start: 0,
      end: "max",
      onUpdate: ({ progress }) => {
        setProgress(progress);
      },
    });

    return () => trigger.kill();
  }, []);

  return (
    <div
      aria-hidden="true"
      className="pointer-events-none fixed inset-x-0 top-0 z-[9999] h-1 bg-black/10"
    >
      <div
        ref={barRef}
        className="h-full w-full bg-[linear-gradient(90deg,#ff4d00,#ffb800)] shadow-[0_0_12px_rgba(255,77,0,0.45)]"
      />
    </div>
  );
}
```

