```tsx
import { ScrollProgress } from "@/components/scroll-progress";

export default function RootLayout({
  children,
}: Readonly<{ children: React.ReactNode }>) {
  return (
    <html lang="es">
      <body>
        <ScrollProgress />
        {children}
      </body>
    </html>
  );
}
```

`quickSetter` evita renders de React y actualiza directamente `scaleX` desde `ScrollTrigger.onUpdate`.
